   "code": "KEY=$(curl -s -X POST \"$SOLEIL_API/uploads?board=$BOARD\" \\\n  -H \"Authorization: Bearer $SOLEIL_TOKEN\" \\\n  -H \"Content-Type: image/jpeg\" \\\n  --data-binary @frame.jpg | jq -r .image_key)\n\ncurl -s -X POST \"$SOLEIL_API/boards/$BOARD/cards\" \\\n  -H \"Authorization: Bearer $SOLEIL_TOKEN\" -H \"Content-Type: application/json\" \\\n  -H \"Idempotency-Key: $(uuidgen)\" \\\n  -d \"{\\\"kind\\\":\\\"image\\\",\\\"image_key\\\":\\\"$KEY\\\",\\\"alt\\\":\\\"Diner counter, night\\\"}\""
